shellCommands.command:
cat > /tmp/test-store.mjs << 'EOF'
import { listBooks, addBook, markFinished, getBook, updateNotes } from '/workspace/lib/books.ts';
EOF
# Use tsx if available, else use a simpler approach with node loader
node --experimental-strip-types -e "
import('./lib/books.ts').then(async (m) => {
  const before = await m.listBooks();
  console.log('Initial:', JSON.stringify(before));
  const b1 = await m.addBook({ title: 'The Pragmatic Programmer', author: 'Hunt & Thomas' });
  console.log('Added:', b1.id, b1.title);
  const b2 = await m.addBook({ title: 'Project Hail Mary', author: 'Andy Weir' });
  console.log('Added:', b2.id, b2.title);
  const afterAdd = await m.listBooks();
  console.log('After add:', afterAdd.reading.length, 'reading,', afterAdd.finished.length, 'finished');
  await m.markFinished(b2.id);
  const afterFinish = await m.listBooks();
  console.log('After finish b2:', afterFinish.reading.length, 'reading,', afterFinish.finished.length, 'finished');
  await m.updateNotes(b1.id, 'Great book about being pragmatic with code.');
  const detail = await m.getBook(b1.id);
  console.log('Notes saved:', JSON.stringify(detail.notes));
}).catch((e) => { console.error('ERR', e); process.exit(1); });
"
